"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["87779"],{248395(n){n.exports=JSON.parse('{"id":13548,"title":"\u9879\u76EE\u5206\u6790","description":"# 01-project \u89C4\u5219\u751F\u6210\u63D0\u793A\u8BCD\uFF08Bootstrap Prompt\uFF09\\n\\n> **\u7528\u9014**\uFF1A\u62FF\u5230\u4E00\u4E2A**\u65B0\u9879\u76EE\u4EE3\u7801\u5E93**\u65F6\uFF0C\u5C06\u672C\u6587\u5168\u6587\uFF08\u6216\u300C\u6309 `00-bootstrap-prompt.md` \u6267\u884C\u300D\uFF09\u53D1\u7ED9 Agent\uFF0C\u8BA9\u5176**\u53EA\u5206\u6790\u3001\u53EA\u8F93\u51FA** `.rules/01-project/` \u4E0B\u7684\u89C4\u5219\u6587\u4EF6\u5185\u5BB9\u3002  \\n> **\u4E0D\u751F\u6210** `02-workflow/`\uFF08\u5DE5\u4F5C\u6D41\u56FA\u5B9A\uFF0C\u76F4\u63A5\u590D\u5236\u672C\u4ED3\u5E93\uFF09\u548C `03-extensions/`\uFF08\u6309\u5B9E\u9645 MCP/Skill \u518D\u914D\uFF09\u3002  \\n> **\u8FED\u4EE3**\uFF1A\u9879\u76EE\u6F14\u8FDB\u540E\uFF0C\u91CD\u65B0\u8FD0\u884C\u672C\u63D0\u793A\u8BCD\u6216\u624B\u5DE5\u589E\u8865\u5BF9\u5E94 `.mdc`\u3002\\n\\n---\\n\\n## \u4E00\u3001\u590D\u5236\u7ED9 Agent \u7684\u63D0\u793A\u8BCD\uFF08\u5F00\u59CB\uFF09\\n\\n```markdown\\n# \u89D2\u8272\\n\\n\u4F60\u662F\u8D44\u6DF1\u8F6F\u4EF6\u67B6\u6784\u5E08 + AI \u5DE5\u7A0B\u89C4\u5219\u7F16\u5199\u8005\u3002\u4EFB\u52A1\uFF1A\u9605\u8BFB\u6211\u63D0\u4F9B\u7684**\u65B0\u9879\u76EE\u4EE3\u7801\u5E93**\uFF0C\u751F\u6210 `.rules/01-project/` \u76EE\u5F55\u4E0B\u7684 Cursor \u89C4\u5219\u6587\u4EF6\uFF08`.mdc`\uFF09\u3002\\n\\n# \u80CC\u666F\uFF1A01-project \u662F\u4EC0\u4E48\\n\\n`.rules/01-project/` \u5B58\u653E**\u9879\u76EE\u8BF4\u660E**\u2014\u2014\u968F\u9879\u76EE\u5B9A\u5236\u3001\u53EF\u6301\u7EED\u4F18\u5316\uFF1A\\n\\n| \u5E8F\u53F7\u6587\u4EF6 | \u804C\u8D23 |\\n|----------|------|\\n| `00-project-overview.mdc` | \u9879\u76EE\u5B9A\u4F4D\u3001\u6280\u672F\u6808\u3001\u76EE\u5F55\u6811\u3001\u8DEF\u7531/\u5165\u53E3\u3001\u6587\u6863\u4E0E\u89C4\u5219\u7D22\u5F15 |\\n| `01-project-architecture.mdc` | \u5206\u5C42\u67B6\u6784\u3001\u4F9D\u8D56\u65B9\u5411\u3001\u6A21\u5757\u8FB9\u754C |\\n| `02-{domain}-*.mdc` \u2026 | **\u9886\u57DF\u4E13\u9879**\uFF08\u6309\u9879\u76EE\u8BC6\u522B\uFF0C0\uFF5EN \u4E2A\uFF1B\u65E0\u5219\u8DF3\u8FC7\uFF09 |\\n\\n`02-workflow/` = \u5F00\u53D1\u6D41\u7A0B\uFF08\u56FA\u5B9A\uFF0C\u52FF\u6539\uFF09\u3002  \\n`03-extensions/` = MCP / Skills / \u53C2\u8003\u5E93\uFF08\u672C\u4EFB\u52A1\u4E0D\u751F\u6210\uFF09\u3002\\n\\n# \u8F93\u5165\uFF08\u6211\u4F1A\u63D0\u4F9B\uFF09\\n\\n- [ ] \u4ED3\u5E93\u6839\u8DEF\u5F84 / \u5DF2\u6253\u5F00\u7684 workspace\\n- [ ] \uFF08\u53EF\u9009\uFF09\u4E00\u53E5\u8BDD\u4EA7\u54C1\u5B9A\u4F4D\\n- [ ] \uFF08\u53EF\u9009\uFF09\u5FC5\u987B\u9075\u5B88\u7684\u6280\u672F\u7EA6\u675F\uFF08\u8BED\u8A00\u7248\u672C\u3001\u7981\u6539\u76EE\u5F55\u7B49\uFF09\\n\\n# \u5206\u6790\u6B65\u9AA4\uFF08\u5FC5\u987B\u6267\u884C\uFF0C\u7981\u6B62\u51ED\u8BB0\u5FC6\uFF09\\n\\n\u6309\u987A\u5E8F\u5B8C\u6210\uFF0C\u7ED3\u8BBA\u987B\u80FD\u5BF9\u5E94**\u771F\u5B9E\u8DEF\u5F84**\uFF1A\\n\\n1. **\u603B\u89C8**\\n   - \u8BFB\u6839 `README*`\u3001`package.json` / `pyproject.toml` / `go.mod` / `pom.xml` \u7B49\\n   - \u8BC6\u522B\uFF1A\u524D\u7AEF / \u540E\u7AEF / \u79FB\u52A8\u7AEF / \u5355\u4F53 /  monorepo\\n   - \u8BB0\u5F55\u7248\u672C\uFF1ANode\u3001Python\u3001\u6846\u67B6\u4E3B\u7248\u672C\\n\\n2. **\u76EE\u5F55\u6811**\\n   - \u5217\u51FA 2\uFF5E3 \u5C42\u76EE\u5F55\uFF08`Glob` / `tree`\uFF09\uFF0C\u6807\u6CE8\u6BCF\u4E2A\u9876\u5C42\u76EE\u5F55\u804C\u8D23\\n   - \u533A\u5206\uFF1A\u4E1A\u52A1\u4EE3\u7801 / \u914D\u7F6E / \u6587\u6863 / \u811A\u672C / \u751F\u6210\u7269 / \u6D4B\u8BD5\\n\\n3. **\u67B6\u6784**\\n   - \u627E\u73B0\u6709\u5206\u5C42\uFF1A\u8DEF\u7531/Controller\u3001Service\u3001Model\u3001UI\u3001API Client \u7B49\\n   - \u753B\u6E05**\u4F9D\u8D56\u65B9\u5411**\uFF08\u8C01\u53EF\u4EE5 import \u8C01\uFF09\\n   - \u627E\u53CD\u4F8B\uFF1A\u9875\u9762\u91CC\u76F4\u63A5 fetch\u3001\u5FAA\u73AF\u4F9D\u8D56\u3001God \u6587\u4EF6\\n\\n4. **\u5165\u53E3\u4E0E\u8DEF\u7531**\\n   - Web\uFF1A\u8DEF\u7531\u8868\u3001Layout\\n   - API\uFF1AOpenAPI / \u8DEF\u7531\u6CE8\u518C\u6587\u4EF6 / `@app.get` \u5217\u8868\\n   - App\uFF1A\u4E3B\u5BFC\u822A Tab\u3001deep link\\n\\n5. **\u9886\u57DF\u80FD\u529B**\uFF08\u51B3\u5B9A\u662F\u5426\u8981 `02+` \u89C4\u5219\uFF09\\n   - AI / LLM / Prompt / RAG / Agent\\n   - \u9274\u6743 / \u652F\u4ED8 / \u5B9E\u65F6\u901A\u4FE1 / \u591A\u7AEF\u540C\u6B65\\n   - \u4EC5\u5F53\u5B58\u5728**\u53EF\u6267\u884C\u7684\u67B6\u6784\u7EA6\u675F**\u65F6\u624D\u65B0\u589E\u9886\u57DF `.mdc`\uFF0C\u4E0D\u8981\u51D1\u6570\\n\\n6. **\u6587\u6863\u4E0E\u914D\u7F6E**\\n   - \u73B0\u6709 `docs/`\u3001`.docs/`\u3001`doc/` \u7D22\u5F15\\n   - \u73AF\u5883\u53D8\u91CF\u3001`.env.example`\u3001\u5BC6\u94A5\u5B58\u653E\u65B9\u5F0F\uFF08\u53EA\u63CF\u8FF0\u89C4\u8303\uFF0C**\u4E0D\u8F93\u51FA\u771F\u5B9E\u5BC6\u94A5**\uFF09\\n\\n7. **\u5F85\u786E\u8BA4\u9879**\\n   - \u65E0\u6CD5\u4ECE\u4EE3\u7801\u786E\u8BA4\u7684\u5185\u5BB9\uFF0C\u5217\u5165\u300C\u5F85\u786E\u8BA4\u300D\uFF0C**\u7981\u6B62\u7F16\u9020**\\n\\n# \u8F93\u51FA\u8981\u6C42\\n\\n## \u683C\u5F0F\uFF08\u6BCF\u4E2A .mdc \u5FC5\u987B\uFF09\\n\\n```yaml\\n---\\ndescription: \u4E00\u53E5\u8BDD\u8BF4\u660E\uFF08\u4E2D\u6587\uFF09\\nalwaysApply: true   # overview \u7528 false\uFF1Barchitecture \u4E0E\u9886\u57DF\u89C4\u5219\u901A\u5E38 true\\n---\\n```\\n\\n\u6B63\u6587**\u5FC5\u987B**\u542B\u4E09\u7AE0\uFF1A\\n\\n```markdown\\n## \u9002\u7528\u8303\u56F4\\n## \u5FC5\u987B\u9879\\n## \u7981\u6B62\u9879\\n```\\n\\n\u53EF\u9009\uFF1A`## \u793A\u4F8B`\uFF08\u6BCF\u6587\u4EF6\u81F3\u5C11 1 \u7EC4 Do / Don\'t\uFF09\\n\\n## \u5177\u8C61\u5316\u539F\u5219\uFF08\u7981\u6B62\u6A21\u7CCA\uFF09\\n\\n| \u7981\u6B62\u5199 | \u5FC5\u987B\u5199 |\\n|--------|--------|\\n| \u300C\u9AD8\u8D28\u91CF\u4EE3\u7801\u300D | \u5355\u6587\u4EF6 \u2264300 \u884C\u3001\u9875\u9762 \u2264200 \u884C\u4E1A\u52A1\u903B\u8F91\u62BD hook |\\n| \u300C\u4F18\u96C5\u67B6\u6784\u300D | `app/` \u2192 `services/` \u2192 `types/`\uFF0C\u7981\u6B62\u53CD\u5411\u4F9D\u8D56 |\\n| \u300C\u6CE8\u610F\u5B89\u5168\u300D | \u5BC6\u94A5\u4EC5 env / secure-store\uFF1B\u7981\u6B62\u5165\u5E93 |\\n| \u300C\u76F8\u5173\u6A21\u5757\u300D | \u7CBE\u786E\u8DEF\u5F84\uFF1A`backend/routers/chat.py` |\\n\\n## \u4EA4\u4ED8\u6E05\u5355\\n\\n### \u5FC5\u987B\u751F\u6210\\n\\n#### \u6587\u4EF6 1\uFF1A`00-project-overview.mdc`\\n\\n\u987B\u5305\u542B\uFF1A\\n\\n- **\u9879\u76EE\u5B9A\u4F4D**\uFF1A1\uFF5E3 \u53E5\u8BDD + \u76EE\u6807\u7528\u6237/\u573A\u666F\\n- **\u6A21\u5757\u8868**\uFF1A\u8DEF\u5F84 | \u6280\u672F\u6808\\n- **\u4ED3\u5E93\u76EE\u5F55\u6811**\uFF08`text` \u4EE3\u7801\u5757\uFF0C2\uFF5E3 \u5C42\uFF0C\u6CE8\u91CA\u804C\u8D23\uFF09\\n- **\u5165\u53E3/\u8DEF\u7531**\uFF08\u82E5\u6709\uFF09\\n- **\u6587\u6863\u7D22\u5F15\u8868**\uFF08\u8DEF\u5F84\u5FC5\u987B\u5B58\u5728\u6216\u6807 `[\u5F85\u786E\u8BA4]`\uFF09\\n- **\u89C4\u5219\u7D22\u5F15**\uFF1A\u6307\u5411 `02-workflow/00-workflow-guide.mdc`\uFF08\u5360\u4F4D\u5373\u53EF\uFF09\\n- **\u7981\u6B62\u9879**\uFF1A\u7981\u6B62\u786C\u7F16\u7801\u5BC6\u94A5\u3001\u7981\u6B62\u628A overview \u5F53\u552F\u4E00\u89C4\u8303\\n\\n`alwaysApply: false`\\n\\n---\\n\\n#### \u6587\u4EF6 2\uFF1A`01-project-architecture.mdc`\\n\\n\u987B\u5305\u542B\uFF1A\\n\\n- \u6BCF\u4E2A\u4E3B\u8981\u4EE3\u7801\u76EE\u5F55\u4E00\u884C\uFF1A**\u76EE\u5F55 | \u804C\u8D23**\\n- **\u4F9D\u8D56\u65B9\u5411**\uFF08\u7BAD\u5934\u4E00\u884C\u5199\u6E05\uFF09\\n- \u6309\u5C42\u5217\u51FA **\u7981\u6B62** \u7684\u8DE8\u5C42\u884C\u4E3A\uFF08\u22654 \u6761\uFF09\\n- **\u6587\u6863\u540C\u6B65**\uFF1A\u67B6\u6784\u53D8\u66F4\u66F4\u65B0\u54EA\u4E2A docs \u8DEF\u5F84\\n- Do/Don\'t \u793A\u4F8B\u5404 1 \u7EC4\\n\\n`alwaysApply: true`\\n\\n---\\n\\n### \u6309\u9700\u751F\u6210\uFF080\uFF5EN \u4E2A\uFF09\\n\\n#### \u6587\u4EF6 3+\uFF1A`02-{domain}-{topic}.mdc`\u3001`03-...`\\n\\n**\u4EC5\u5F53**\u9879\u76EE\u5B58\u5728\u660E\u786E\u9886\u57DF\u7EA6\u675F\u65F6\u751F\u6210\uFF0C\u4F8B\u5982\uFF1A\\n\\n| \u9879\u76EE\u7C7B\u578B | \u53EF\u80FD\u7684\u9886\u57DF\u89C4\u5219 |\\n|----------|----------------|\\n| AI \u804A\u5929 / RP | `02-ai-prompt.mdc`\u3001`03-provider-tooling.mdc` |\\n| \u7535\u5546 | `02-order-payment.mdc` |\\n| \u7EAF CRUD \u540E\u53F0 | \u53EF\u4E0D\u751F\u6210\uFF0C\u5728 overview \u6CE8\u660E\u300C\u65E0\u989D\u5916\u9886\u57DF\u89C4\u5219\u300D |\\n\\n\u6BCF\u4E2A\u9886\u57DF\u6587\u4EF6\u987B\u5305\u542B\uFF1A\\n\\n- \u9002\u7528\u8303\u56F4\uFF08\u7CBE\u786E\u76EE\u5F55\uFF09\\n- \u5FC5\u987B\u9879\uFF08\u22655 \u6761\u53EF\u68C0\u67E5\u6761\u76EE\uFF09\\n- \u7981\u6B62\u9879\uFF08\u22654 \u6761\uFF09\\n- \u4E0E\u73B0\u6709\u4EE3\u7801\u7684\u5BF9\u9F50\u8BF4\u660E\uFF08\u5F15\u7528 1\uFF5E2 \u4E2A\u771F\u5B9E\u6587\u4EF6\u4F5C\u8303\u4F8B\uFF09\\n\\n**\u4E0D\u8981**\u628A\u901A\u7528\u7F16\u7801\u89C4\u8303\u585E\u8FDB 01-project\uFF08\u90A3\u4E9B\u5C5E\u4E8E `02-workflow/`\uFF09\u3002\\n\\n---\\n\\n## \u8F93\u51FA\u65B9\u5F0F\\n\\n1. \u6309\u6587\u4EF6\u5206\u8282\u8F93\u51FA\uFF0C\u6807\u9898\uFF1A`## \u8F93\u51FA\uFF1A00-project-overview.mdc`\\n2. \u6BCF\u4E2A\u6587\u4EF6\u7ED9\u51FA**\u5B8C\u6574** `.mdc` \u5185\u5BB9\uFF08\u542B frontmatter\uFF09\uFF0C\u53EF\u76F4\u63A5\u843D\u76D8\\n3. \u6587\u672B\u9644\uFF1A\\n   - **\u5F85\u786E\u8BA4\u4E8B\u9879**\u5217\u8868\\n   - **\u5EFA\u8BAE\u4E0B\u6B21 bootstrap \u65F6\u590D\u67E5**\u7684\u8DEF\u5F84\\n   - **\u672A\u751F\u6210\u9886\u57DF\u89C4\u5219\u7684\u539F\u56E0**\uFF08\u82E5\u8DF3\u8FC7\uFF09\\n\\n## \u7981\u6B62\\n\\n- \u7981\u6B62\u672A\u8BFB\u4ED3\u5E93\u5C31\u5199\u76EE\u5F55\u6811\u6216 API \u5217\u8868\\n- \u7981\u6B62\u7F16\u9020\u4E0D\u5B58\u5728\u7684\u8DEF\u5F84\u3001\u5305\u540D\u3001\u8868\u540D\\n- \u7981\u6B62\u8F93\u51FA\u771F\u5B9E API Key\u3001Token\u3001\u5185\u7F51 URL\\n- \u7981\u6B62\u5728\u672C\u4EFB\u52A1\u4E2D\u4FEE\u6539\u4E1A\u52A1\u4EE3\u7801\u6216\u751F\u6210 `02-workflow/` \u5185\u5BB9\\n- \u7981\u6B62\u7528\u300C\u540E\u7EED\u4F18\u5316\u300D\u4EE3\u66FF\u5F53\u524D\u5FC5\u987B\u7684\u67B6\u6784\u63CF\u8FF0\\n\\n# \u5F00\u59CB\\n\\n\u8BF7\u5206\u6790\u5F53\u524D workspace \u4EE3\u7801\u5E93\uFF0C\u6309\u4E0A\u8FF0\u8981\u6C42\u751F\u6210 `.rules/01-project/` \u89C4\u5219\u6587\u4EF6\u3002\\n```\\n\\n---\\n\\n## \u4E8C\u3001\u4F7F\u7528\u8BF4\u660E\uFF08\u7ED9\u4EBA\u770B\uFF09\\n\\n### \u4F55\u65F6\u8FD0\u884C\\n\\n| \u573A\u666F | \u52A8\u4F5C |\\n|------|------|\\n| \u65B0\u9879\u76EE\u63A5\u5165\u672C rules \u4F53\u7CFB | \u8DD1\u4E00\u904D Bootstrap \u2192 \u5199\u5165 `01-project/*.mdc` |\\n| \u5927\u91CD\u6784 / \u6362\u6280\u672F\u6808 | \u91CD\u8DD1\u6216 diff \u589E\u8865 |\\n| \u5C0F\u529F\u80FD | \u76F4\u63A5\u6539\u5BF9\u5E94 `.mdc`\uFF0C\u4E0D\u5FC5\u91CD\u8DD1 |\\n\\n### \u64CD\u4F5C\u6B65\u9AA4\\n\\n```text\\n1. \u786E\u4FDD\u65B0\u9879\u76EE\u5DF2 clone / \u5728 Cursor \u6253\u5F00\\n2. \u4ECE\u300C\u4E00\u3001\u590D\u5236\u7ED9 Agent \u7684\u63D0\u793A\u8BCD\u300D\u4E2D\u590D\u5236 ```markdown ... ``` \u6574\u6BB5\\n3. \u53EF\u9009\uFF1A\u5728\u300C\u8F93\u5165\u300D\u5C0F\u8282\u52FE\u9009\u5E76\u8865\u5145\u4E00\u53E5\u8BDD\u5B9A\u4F4D\\n4. \u53D1\u9001\u7ED9 Agent\\n5. \u5C06\u8F93\u51FA\u7684 .mdc \u5199\u5165\u65B0\u9879\u76EE `.rules/01-project/`\\n6. \u4ECE\u672C\u4ED3\u5E93\u590D\u5236 `.rules/02-workflow/`\u3001`03-extensions/`\uFF08\u6269\u5C55\u6309\u9879\u76EE\u88C1\u526A\uFF09\\n7. \u8FD0\u884C scripts/sync-cursor-rules.ps1\uFF08\u82E5\u6CBF\u7528\u672C\u4ED3\u5E93\u811A\u672C\uFF09\\n```\\n\\n### 01-project \u6587\u4EF6\u5E8F\u53F7\u7EA6\u5B9A\\n\\n| \u5E8F\u53F7 | \u6587\u4EF6\u540D\u6A21\u5F0F | \u8BF4\u660E |\\n|------|------------|------|\\n| `00` | `00-project-overview.mdc` | \u56FA\u5B9A\uFF1A\u603B\u89C8 |\\n| `01` | `01-project-architecture.mdc` | \u56FA\u5B9A\uFF1A\u67B6\u6784 |\\n| `02\uFF5E89` | `02-{domain}-*.mdc` | \u9886\u57DF\u89C4\u5219\uFF0C\u6309\u9879\u76EE\u589E\u51CF |\\n| \u2014 | `00-bootstrap-prompt.md` | \u672C\u6587\u4EF6\uFF0C\u975E Cursor \u89C4\u5219 |\\n\\n\u65B0\u589E\u9886\u57DF\u89C4\u5219\u65F6\uFF1A**\u9012\u589E\u5E8F\u53F7**\uFF0C\u66F4\u65B0 `.rules/README.md` \u7D22\u5F15\u3002\\n\\n### \u672C\u4ED3\u5E93\uFF08C-Chat\uFF09\u5DF2\u843D\u5730\u793A\u4F8B\\n\\n| \u6587\u4EF6 | \u9886\u57DF |\\n|------|------|\\n| `00-project-overview.mdc` | Expo + FastAPI \u603B\u89C8 |\\n| `01-project-architecture.mdc` | RN \u5206\u5C42 + \u540E\u7AEF\u5206\u5C42 |\\n| `02-ai-roleplay-prompt.mdc` | \u89D2\u8272\u5361 / Prompt |\\n| `03-provider-tooling.mdc` | LLM Provider / Tool |\\n\\n\u65B0\u9879\u76EE\u82E5\u65E0 AI \u80FD\u529B\uFF0C\u53EF\u53EA\u4FDD\u7559 `00`\u3001`01` \u4E24\u4E2A\u6587\u4EF6\u3002\\n\\n---\\n\\n## \u4E09\u3001\u4EA7\u51FA\u8D28\u91CF\u81EA\u68C0\uFF08Agent \u5B8C\u6210\u540E\u4EBA\u5DE5\u6216\u811A\u672C\u62BD\u67E5\uFF09\\n\\n- [ ] \u76EE\u5F55\u6811\u4E2D\u6BCF\u4E2A\u8DEF\u5F84\u5728\u4ED3\u5E93\u4E2D\u5B58\u5728\\n- [ ] `01-project-architecture` \u4F9D\u8D56\u65B9\u5411\u4E0E import \u4E60\u60EF\u4E00\u81F4\\n- [ ] \u65E0 `sk-`\u3001`AIza`\u3001password \u7B49\u654F\u611F\u5B57\u9762\u91CF\\n- [ ] \u6BCF\u4E2A `.mdc` \u542B `\u9002\u7528\u8303\u56F4 / \u5FC5\u987B\u9879 / \u7981\u6B62\u9879`\\n- [ ] overview \u7684 `alwaysApply: false`\uFF0Carchitecture \u4E3A `true`\\n- [ ] README.md \u5DF2\u5217\u51FA\u6240\u6709 `01-project/*.mdc`\\n\\n---\\n\\n## \u56DB\u3001\u53D8\u66F4\u8BB0\u5F55\\n\\n| \u65E5\u671F | \u8BF4\u660E |\\n|------|------|\\n| 2026-05-30 | \u521D\u7248\uFF1A\u5BF9\u9F50 `.rules` \u4E09\u5206\u6CD5\uFF0C\u4EC5 bootstrap `01-project` |\\n","remark":"\u9879\u76EE\u5206\u6790","notes":"\u4E3B\u8981\u7528\u4E8E\u65B0\u9879\u76EE\u521D\u59CB\u5316\uFF0C\u5E76\u751F\u6210\u76F8\u5E94\u7684RULES","owner":"liufulicheng","upvotes":1,"downvotes":0,"upvoteDifference":1,"updatedAt":"2026-06-01T01:42:27.737Z"}')}}]);